class Solution {
public:
    int fib(int n) {
        if (n == 0) return 0;
        if (n == 1) return 1;

        long long res[2][2] = {{1, 0}, {0, 1}};
        long long base[2][2] = {{1, 1}, {1, 0}};

        int power = n - 1;
        while (power > 0) {
            if (power & 1) {
                long long temp[2][2] = {{0, 0}, {0, 0}};
                for (int i = 0; i < 2; i++) {
                    for (int j = 0; j < 2; j++) {
                        for (int k = 0; k < 2; k++) {
                            temp[i][j] += res[i][k] * base[k][j];
                        }
                    }
                }
                for (int i = 0; i < 2; i++) {
                    for (int j = 0; j < 2; j++) {
                        res[i][j] = temp[i][j];
                    }
                }
            }

            long long temp2[2][2] = {{0, 0}, {0, 0}};
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    for (int k = 0; k < 2; k++) {
                        temp2[i][j] += base[i][k] * base[k][j];
                    }
                }
            }
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    base[i][j] = temp2[i][j];
                }
            }

            power >>= 1;
        }

        return res[0][0];
    }
};
